import Foundation

/// An artifact effect as heroes4.exe builds it (default_artifacts.cpp 0x659450; dumped by running
/// the builder): `type` (0x37 attack, 0x0a defense, 0x10 HP %, 0x2a speed, 0x19 spell points, 0x1a
/// regen, 0x16 luck, 0x1b morale, 0x17 resistance %, 0x08 army attack %, 0x00 adventure move %, 0x12
/// income, 0x2d spell power %, 0x2f spell cost, 0x2c spellbook, 0x38 ability, 0x2b spell effect, 0x11
/// immunities, 0x09 damage, 0x2e charges, 0x32 skill bonus, 0x3b set ...); `target` 0 the bearer,
/// 1 enemy creatures, 2 enemy heroes, 3 friendly creatures, 4 the other friendly heroes, 5 all.
/// Attack and defense on the bearer are tenths of the shown points; elsewhere percent.
public struct ArtifactEffect {
    public var type: Int, target: Int, amount: Int
    public var melee = true, ranged = true
    public var spell = -1
    public var spells: [Int] = []
    public var skill = -1
    public var ability = ""
    public var income: [Int] = []
    public var land = true, sea = false
    public var perLevel = 0, divisor = 1, damageKind = 0
    public var cost = 0
    public var charges = 0, regen = 0
    public var growth: [Int] = []
    public var required: [Int] = []
    public var subs: [ArtifactEffect] = []
    public init(type: Int, target: Int, amount: Int, melee: Bool = true, ranged: Bool = true, spell: Int = -1, spells: [Int] = [], skill: Int = -1,
                ability: String = "", income: [Int] = [], land: Bool = true, sea: Bool = false, perLevel: Int = 0, divisor: Int = 1, damageKind: Int = 0,
                cost: Int = 0, charges: Int = 0, regen: Int = 0, growth: [Int] = [], required: [Int] = [], subs: [ArtifactEffect] = []) {
        self.type = type; self.target = target; self.amount = amount; self.melee = melee; self.ranged = ranged; self.spell = spell; self.spells = spells
        self.skill = skill; self.ability = ability; self.income = income; self.land = land; self.sea = sea; self.perLevel = perLevel; self.divisor = divisor
        self.damageKind = damageKind; self.cost = cost; self.charges = charges; self.regen = regen; self.growth = growth; self.required = required; self.subs = subs
    }
}

